// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.BitSet;
import java.util.List;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;
import org.junit.jupiter.api.Test;

/** Sort-key (M7), aggregate-bridge (M8), and adaptivity (M9) tests for the fragment tier. */
class FragmentSortAggAdaptivityTest {

	private static long orderedInt(long value) {
		return ValueIds.createId(ValueIds.T_ORD_INTEGER, value + ValueIds.ORDERED_BIAS);
	}

	private static long dateId(int year, int month, int day, int tz) {
		return ValueIds.createId(ValueIds.T_DATE,
				(long) year | (long) month << 13 | (long) day << 17 | (long) tz << 49);
	}

	// ------------------------------------------------------------------
	// M7: sort keys
	// ------------------------------------------------------------------

	@Test
	void dateKeysSortHomogeneousDatesWithoutExactComparisons() {
		long[] ids = { dateId(2024, 3, 1, 7), dateId(2023, 12, 31, 7), dateId(2024, 2, 29, 7) };
		long[] keys = new long[3];
		BitSet escapes = new BitSet();
		int escaped = SortKeyFragments.extractDateKeys(ids, 0, 3, keys, escapes);
		assertThat(escaped).isZero();
		assertThat(keys[1]).isLessThan(keys[2]);
		assertThat(keys[2]).isLessThan(keys[0]);
		assertThat(SortKeyFragments.dateKeysDirectlyComparable(keys[0], keys[1])).isTrue();
	}

	@Test
	void escapedRowsAreFlaggedInTheBitmapNotSentinelKeyed() {
		long[] ids = { dateId(2024, 3, 1, 7), -1L, orderedInt(5), dateId(2020, 1, 1, 2) };
		long[] keys = new long[4];
		BitSet escapes = new BitSet();
		int escaped = SortKeyFragments.extractDateKeys(ids, 0, 4, keys, escapes);
		assertThat(escaped).isEqualTo(2);
		assertThat(escapes.get(1)).isTrue();
		assertThat(escapes.get(2)).isTrue();
		assertThat(escapes.get(0)).isFalse();
		assertThat(escapes.get(3)).isFalse();
		// cross-timezone-class primitive keys are not directly comparable (ambiguous partition)
		assertThat(SortKeyFragments.dateKeysDirectlyComparable(keys[0], keys[3])).isFalse();
	}

	@Test
	void orderedIntegerKeysPreserveNumericOrderAcrossSubtypes() {
		long[] ids = { orderedInt(-5), ValueIds.createId(ValueIds.T_ORD_LONG, 3 + ValueIds.ORDERED_BIAS),
				orderedInt(100), ValueIds.createId(ValueIds.T_LITERAL, 4) };
		long[] keys = new long[4];
		BitSet escapes = new BitSet();
		int escaped = SortKeyFragments.extractOrderedIntegerKeys(ids, 0, 4, keys, escapes);
		assertThat(escaped).isEqualTo(1);
		assertThat(keys[0]).isLessThan(keys[1]);
		assertThat(keys[1]).isLessThan(keys[2]);
		assertThat(escapes.get(3)).isTrue();
	}

	@Test
	void exactFringeCoversEscapesAndBoundaryTies() {
		assertThat(SortKeyFragments.inExactFringe(KernelRuntime.SORT_KEY_ESCAPE, 100)).isTrue();
		assertThat(SortKeyFragments.inExactFringe(100, 100)).isTrue();
		assertThat(SortKeyFragments.inExactFringe(99, 100)).isFalse();
	}

	// ------------------------------------------------------------------
	// M8: primitive aggregate promotion
	// ------------------------------------------------------------------

	private static final class RecordingEscape implements NumericAggregateEscape {
		final List<long[]> promotions = new ArrayList<>();
		final List<long[]> exactValues = new ArrayList<>();

		@Override
		public void promoteScaledLong(int aggregateSite, int group, long unscaledSum, int scale, long count) {
			promotions.add(new long[] { aggregateSite, group, unscaledSum, scale, count });
		}

		@Override
		public void accumulateExact(int aggregateSite, int group, long valueId) {
			exactValues.add(new long[] { aggregateSite, group, valueId });
		}
	}

	@Test
	void primitiveSumsStayLiteralFreeUntilDegradation() {
		RecordingEscape escape = new RecordingEscape();
		PrimitiveSumAccumulator accumulator = new PrimitiveSumAccumulator(0, escape);
		accumulator.accumulate(0, orderedInt(10));
		accumulator.accumulate(0, orderedInt(32));
		accumulator.accumulate(1, orderedInt(5));
		assertThat(accumulator.primitive(0)).isTrue();
		assertThat(accumulator.sum(0)).isEqualTo(42);
		assertThat(accumulator.count(0)).isEqualTo(2);
		assertThat(escape.promotions).isEmpty();
		// a dictionary literal degrades ONLY its group: partial promoted once, value routed exactly
		long literal = ValueIds.createId(ValueIds.T_LITERAL, 9);
		accumulator.accumulate(0, literal);
		assertThat(accumulator.primitive(0)).isFalse();
		assertThat(accumulator.primitive(1)).isTrue();
		assertThat(escape.promotions).hasSize(1);
		assertThat(escape.promotions.get(0)).containsExactly(0, 0, 42, 0, 2);
		assertThat(escape.exactValues).hasSize(1);
		assertThat(escape.exactValues.get(0)).containsExactly(0, 0, literal);
		// later values for the degraded group keep routing exactly, without re-promotion
		accumulator.accumulate(0, orderedInt(1));
		assertThat(escape.promotions).hasSize(1);
		assertThat(escape.exactValues).hasSize(2);
	}

	@Test
	void overflowDegradesInsteadOfWrapping() {
		RecordingEscape escape = new RecordingEscape();
		PrimitiveSumAccumulator accumulator = new PrimitiveSumAccumulator(3, escape);
		long huge = (1L << 55) - 1;
		accumulator.accumulate(0, orderedInt(huge));
		long previous = accumulator.sum(0);
		for (int i = 0; i < 600; i++) {
			accumulator.accumulate(0, orderedInt(huge));
			if (!accumulator.primitive(0)) {
				break;
			}
			assertThat(accumulator.sum(0)).isGreaterThan(previous);
			previous = accumulator.sum(0);
		}
		// 2^63 / 2^55 ≈ 256 additions force the overflow degrade well within the loop
		assertThat(accumulator.primitive(0)).isFalse();
		assertThat(escape.promotions).hasSize(1);
		assertThat(escape.promotions.get(0)[0]).isEqualTo(3);
	}

	@Test
	void promoteAllReHomesOnlyGroupsWithValues() {
		RecordingEscape escape = new RecordingEscape();
		PrimitiveSumAccumulator accumulator = new PrimitiveSumAccumulator(0, escape, 8);
		accumulator.accumulate(2, orderedInt(7));
		accumulator.promoteAll();
		assertThat(escape.promotions).hasSize(1);
		assertThat(escape.promotions.get(0)).containsExactly(0, 2, 7, 0, 1);
	}

	// ------------------------------------------------------------------
	// M9: adaptivity
	// ------------------------------------------------------------------

	@Test
	void variantSelectorConvergesOnTheCheapestArmButKeepsExploring() {
		FragmentAdaptivity.VariantSelector selector = new FragmentAdaptivity.VariantSelector(3, 16);
		int[] chosen = new int[3];
		for (int i = 0; i < 480; i++) {
			int variant = selector.choose();
			chosen[variant]++;
			// variant 1 is the cheapest
			selector.observe(variant, variant == 1 ? 10 : 100);
		}
		assertThat(chosen[1]).isGreaterThan(chosen[0] + chosen[2]);
		assertThat(chosen[0]).isPositive(); // deterministic exploration keeps sampling the others
		assertThat(chosen[2]).isPositive();
	}

	@Test
	void permutationReordersMostSelectiveFirstWithoutRecompiling() {
		FragmentAdaptivity.Permutation permutation = new FragmentAdaptivity.Permutation(3);
		assertThat(permutation.siteAt(0)).isZero();
		permutation.observe(0, 1000, 10); // barely selective
		permutation.observe(1, 1000, 900); // highly selective
		permutation.observe(2, 1000, 500);
		permutation.reorderBySelectivity();
		assertThat(permutation.siteAt(0)).isEqualTo(1);
		assertThat(permutation.siteAt(1)).isEqualTo(2);
		assertThat(permutation.siteAt(2)).isZero();
	}
}
